// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.deal(address(this), depositAmount);
        address(c).call{value: depositAmount}("");
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(address(c).balance == 0);
        }
    }
}
